// Registration validates every requested size, but builds one small atlas.
// All other sizes retain the original pixel size and are created on first use.
static qboolean Font_PrepareDemandSizes(ft2_font_t *font, const float *requested)
{
	int s, i, smallest = -1;
	for (s = 0; s < MAX_FONT_SIZES && requested[s] >= 0; ++s)
	{
		float size = Font_VirtualToRealSize(requested[s]);
		// Keep Font_LoadSize's existing normalization, including default size 16.
		if (!(size > 0.001f && size < 1000.0f)) size = 16;
		if (size < 2 || !Font_LoadSize(font, size, true)) continue;
		for (i = 0; i < font->ios_requested_count; ++i)
			if (font->ios_requested_sizes[i] == size) break;
		if (i < font->ios_requested_count) continue;
		font->ios_requested_sizes[i] = size;
		++font->ios_requested_count;
		if (smallest < 0 || size < font->ios_requested_sizes[smallest]) smallest = i;
	}
	return smallest >= 0 && Font_LoadSize(font, font->ios_requested_sizes[smallest], false);
}

static qboolean Font_EnsureDemandSize(ft2_font_t *font, float width, float height)
{
	int i, best = -1;
	float value = 0;
	if (font->ios_demand_failed) return false;
	for (i = 0; i < font->ios_requested_count; ++i)
	{
		float size = font->ios_requested_sizes[i];
		float distance = 0.5 * (fabs(size - width) + fabs(size - height));
		if (best < 0 || distance < value || (distance == value && size > font->ios_requested_sizes[best]))
		{
			best = i;
			value = distance;
		}
	}
	if (best < 0) return true; // Non-registered/internal font: existing map lookup.
	if (Font_LoadSize(font, font->ios_requested_sizes[best], false)) return true;
	// Font_LoadSize already reports the failure and unloads the font. Do not
	// dereference its old maps or retry a freed face on the next draw.
	font->ios_demand_failed = true;
	return false;
}
